function nudgeShapePath(path,seed,amplitude){
  const numberPattern=/-?\d+(?:\.\d+)?/g;
  const values=[...path.matchAll(numberPattern)].map((match,point)=>{
    const wave=Math.sin((point+1)*(seed+1)*1.37)+Math.cos((point+3)*(seed+2)*.61)*.42;
    return Number(match[0])+wave*amplitude;
  });
  if(/Z\s*$/i.test(path)&&values.length>=4){
    values[values.length-2]=values[0];
    values[values.length-1]=values[1];
  }
  let point=0;
  return path.replace(numberPattern,()=>values[point++].toFixed(1));
}
