  $$('[data-builder-key] button').forEach(button=>button.addEventListener("click",()=>{const key=button.closest("[data-builder-key]").dataset.builderKey;const value=button.dataset.shapeValue;if(key==="shape")state.animal=normalizeShapeId(value);else state.shapeProfile[key]=value;saveShapeProfile();renderAnimals();applyAnimalUI(getAnimal(state.animal),true);renderRecommendations();renderCrews();renderPassport();showToast(`拼块已更新：${getAnimal(state.animal).name}`)}));
